package thingworx.tasks

import org.gradle.api.DefaultTask
import org.gradle.api.file.ConfigurableFileCollection
import org.gradle.api.file.DirectoryProperty
import org.gradle.api.file.RegularFileProperty
import org.gradle.api.tasks.InputDirectory
import org.gradle.api.tasks.InputFiles
import org.gradle.api.tasks.OutputFile
import org.gradle.api.tasks.PathSensitive
import org.gradle.api.tasks.PathSensitivity
import org.gradle.api.tasks.CacheableTask
import org.gradle.api.tasks.TaskAction

/**
 * Writes the extension metadata.xml generated by the DAP processor with its
 * {@code <JarResources>} replaced by exactly the jars packaged in lib/common.
 */
@CacheableTask
abstract class ExtensionMetadata extends DefaultTask {
    /** The DAP output directory containing metadata.xml. */
    @InputDirectory
    @PathSensitive(PathSensitivity.RELATIVE)
    abstract DirectoryProperty getGeneratedEntities()

    @InputFiles
    @PathSensitive(PathSensitivity.NAME_ONLY)
    abstract ConfigurableFileCollection getJars()

    @OutputFile
    abstract RegularFileProperty getOutputFile()

    @TaskAction
    void write() {
        String content = generatedEntities.file('metadata.xml').get().asFile.text
        def names = jars.files.findAll { it.name.endsWith('.jar') }.collect { it.name }.unique().sort()
        if (!names.isEmpty()) {
            def resources = names.collect { "                <FileResource description=\"\" file=\"${it}\" type=\"JAR\"/>" }.join('\n')
            content = content.replaceAll(/(?s)<JarResources>.*?<\/JarResources>/,
                    java.util.regex.Matcher.quoteReplacement("<JarResources>\n${resources}\n            </JarResources>"))
        }
        outputFile.get().asFile.text = content
    }
}
